window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0e2d5e33c84c4d5b"]={"versions": [{"id": "FIG-0e2d5e33c84c4d5b", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Artefakt- und Containerdiagramm zur Spezifikation des Update and Configuration Management (UCM) der AUTOSAR Adaptive Platform. Das Diagramm modelliert den logischen und physischen Aufbau eines Bereitstellungs-Pakets (<code>Software Package</code>) für Software-Cluster und zugehörige Artefakte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine hierarchisch geschachtelte Dateistruktur:</p>\n<ul class=\"fig-list\"><li>Äußere Kapselung: <code>Software Package A</code> als Dateicontainer mit umgeknickter Ecke.\n</li><li>Signierter Bereich: <code>Signed container</code>, der als geschachteltes Dokumentenartefakt zwei Hauptblöcke umfasst:\n<ul class=\"fig-list\"><li>Ein Dateibündel mit den Elementen <code>Executables</code> (ausführbare Binärdateien), <code>Data</code> (Konfigurations-, Persistenz- oder Kalibrierdaten) und <code>Manifests</code> (anwendungsspezifische Beschreibungsdateien).\n</li><li><code>Software Package Manifest</code>: Separates Beschreibungsdokument innerhalb des signierten Containers zur Steuerung von Metadaten, Abhängigkeiten und Versionierung.\n</li></ul>\n</li><li>Integritäts- und Sicherheitskomponente: <code>Signature</code> (blau hervorgehobener Block am unteren Ende des Pakets außerhalb des <code>Signed container</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Daten- und Paketierungsmodell ohne dynamische Ablauf- oder Kontrollflusselemente. Die implizite Verarbeitungsreihenfolge sieht den Empfang des Gesamtpakets, die kryptografische Verifikation des <code>Signed container</code> mittels der anhängenden <code>Signature</code> sowie das anschließende Auslesen des <code>Software Package Manifest</code> und Entpacken/Installieren von Executables, Daten und Manifesten vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für UCM-Verifikationsroutinen und Paketgeneratoren. Die Trennung zeigt auf, welche Bestandteile von der Signatur erfasst werden müssen: Sowohl die Software-Cluster-Nutzdaten (<code>Executables</code>, <code>Data</code>, <code>Manifests</code>) als auch das <code>Software Package Manifest</code> liegen zwingend im Gültigkeitsbereich des <code>Signed container</code>, während die kryptografische <code>Signature</code> den Container validiert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5d7ad519ee012a91", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Artefakt- und Containerdiagramm zur Spezifikation des Update and Configuration Management (UCM) der AUTOSAR Adaptive Platform. Das Diagramm modelliert den logischen und physischen Aufbau eines Bereitstellungs-Pakets (<code>Software Package</code>) für Software-Cluster und zugehörige Artefakte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine hierarchisch geschachtelte Dateistruktur:</p>\n<ul class=\"fig-list\"><li>Äußere Kapselung: <code>Software Package A</code> als Dateicontainer mit umgeknickter Ecke.\n</li><li>Signierter Bereich: <code>Signed container</code>, der als geschachteltes Dokumentenartefakt zwei Hauptblöcke umfasst:\n<ul class=\"fig-list\"><li>Ein Dateibündel mit den Elementen <code>Executables</code> (ausführbare Binärdateien), <code>Data</code> (Konfigurations-, Persistenz- oder Kalibrierdaten) und <code>Manifests</code> (anwendungsspezifische Beschreibungsdateien).\n</li><li><code>Software Package Manifest</code>: Separates Beschreibungsdokument innerhalb des signierten Containers zur Steuerung von Metadaten, Abhängigkeiten und Versionierung.\n</li></ul>\n</li><li>Integritäts- und Sicherheitskomponente: <code>Authentication tag</code> (blau hervorgehobener Block mit roter Umrandung am unteren Ende des Pakets außerhalb des <code>Signed container</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Daten- und Paketierungsmodell ohne dynamische Ablauf- oder Kontrollflusselemente. Die implizite Verarbeitungsreihenfolge sieht den Empfang des Gesamtpakets, die kryptografische Integritäts- und Authentizitätsprüfung des <code>Signed container</code> anhand des <code>Authentication tag</code> sowie das anschließende Auslesen des <code>Software Package Manifest</code> und Entpacken/Installieren von Executables, Daten und Manifesten vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für UCM-Verifikationsroutinen und Paketgeneratoren. Der Sicherheitsnachweis ist als <code>Authentication tag</code> spezifiziert, wodurch neben digitalen Signaturen auch Message Authentication Codes (MAC) zulässig sind. Sowohl die Software-Cluster-Nutzdaten (<code>Executables</code>, <code>Data</code>, <code>Manifests</code>) als auch das <code>Software Package Manifest</code> liegen zwingend im Gültigkeitsbereich des <code>Signed container</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-351652e4f7953515", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Artefakt- und Containerdiagramm zur Spezifikation des Update and Configuration Management (UCM) der AUTOSAR Adaptive Platform. Das Diagramm modelliert den logischen und physischen Aufbau eines Bereitstellungs-Pakets (<code>Software Package</code>) für Software-Cluster und zugehörige Artefakte.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine hierarchisch geschachtelte Dateistruktur:</p>\n<ul class=\"fig-list\"><li>Äußere Kapselung: <code>Software Package A</code> als Dateicontainer mit umgeknickter Ecke.\n</li><li>Signierter Bereich: <code>Signed container</code>, der als geschachteltes Dokumentenartefakt zwei Hauptblöcke umfasst:\n<ul class=\"fig-list\"><li>Ein Dateibündel mit den Elementen <code>Executables</code> (ausführbare Binärdateien), <code>Data</code> (Konfigurations-, Persistenz- oder Kalibrierdaten) und <code>Manifests</code> (anwendungsspezifische Beschreibungsdateien).\n</li><li><code>Software Package Manifest</code>: Separates Beschreibungsdokument innerhalb des signierten Containers zur Steuerung von Metadaten, Abhängigkeiten und Versionierung.\n</li></ul>\n</li><li>Integritäts- und Sicherheitskomponente: <code>Authentication tag</code> (blau hervorgehobener Block mit roter Umrandung am unteren Ende des Pakets außerhalb des <code>Signed container</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Daten- und Paketierungsmodell ohne dynamische Ablauf- oder Kontrollflusselemente. Die implizite Verarbeitungsreihenfolge sieht den Empfang des Gesamtpakets, die kryptografische Integritäts- und Authentizitätsprüfung des <code>Signed container</code> anhand des <code>Authentication tag</code> sowie das anschließende Auslesen des <code>Software Package Manifest</code> und Entpacken/Installieren von Executables, Daten und Manifesten vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Relevanz für UCM-Verifikationsroutinen und Paketgeneratoren. Der Sicherheitsnachweis ist als <code>Authentication tag</code> spezifiziert, wodurch neben digitalen Signaturen auch Message Authentication Codes (MAC) zulässig sind. Sowohl die Software-Cluster-Nutzdaten (<code>Executables</code>, <code>Data</code>, <code>Manifests</code>) als auch das <code>Software Package Manifest</code> liegen zwingend im Gültigkeitsbereich des <code>Signed container</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0e2d5e33c84c4d5b", "to": "FIG-5d7ad519ee012a91", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Element <code>Signature</code> durch <code>Authentication tag</code> ersetzt (Verschiebung bzw. Generalisierung des kryptografischen Integritäts- und Authentifizierungsnachweises von einer asymmetrischen Signatur auf ein allgemeines Authentifizierungs-Tag/MAC).\n</li><li>Höhere Bildauflösung und Schärfung der Vektorelemente/Typografie.\n</li></ul>"}, {"from": "FIG-5d7ad519ee012a91", "to": "FIG-351652e4f7953515", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
